package dev.helios.test_app

import org.springframework.http.HttpStatus
import org.springframework.http.ResponseEntity
import org.springframework.web.bind.annotation.*
import java.util.UUID

@RestController
@RequestMapping("/posts")
class PostController(private val postRepository: PostRepository, private val jobs: JobPublisher) {

    @GetMapping
    fun list(): List<Post> = postRepository.findAll()

    @GetMapping("/{id}")
    fun getById(@PathVariable id: UUID): ResponseEntity<Post> {
        val item = postRepository.findById(id).orElse(null)
            ?: return ResponseEntity.notFound().build()
        return ResponseEntity.ok(item)
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    fun create(@RequestBody body: Post): Post = postRepository.save(body)
        .also { jobs.publish("""{"event":"post.created","id":"${it.id}"}""") }

    @PutMapping("/{id}")
    fun update(@PathVariable id: UUID, @RequestBody body: Post): ResponseEntity<Post> {
        if (!postRepository.existsById(id)) return ResponseEntity.notFound().build()
        val updated = body.copy(id = id)
        return ResponseEntity.ok(postRepository.save(updated))
    }

    @DeleteMapping("/{id}")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    fun delete(@PathVariable id: UUID) {
        if (!postRepository.existsById(id)) throw org.springframework.web.server.ResponseStatusException(
            org.springframework.http.HttpStatus.NOT_FOUND
        )
        postRepository.deleteById(id)
    }
}

package dev.helios.test_app

import org.springframework.cache.annotation.CacheEvict
import org.springframework.cache.annotation.Cacheable
import org.springframework.data.jpa.repository.JpaRepository
import java.util.Optional
import java.util.UUID

/** Cache-aside on reads by id (Redis, 60s TTL); saves and deletes evict the entry. */
interface PostRepository : JpaRepository<Post, UUID> {
    @Cacheable("posts", key = "#p0", unless = "#result == null")
    override fun findById(id: UUID): Optional<Post>

    @CacheEvict("posts", key = "#p0.id", condition = "#p0.id != null")
    override fun <S : Post> save(entity: S): S

    @CacheEvict("posts", key = "#p0")
    override fun deleteById(id: UUID)
}

