package dev.helios.test_app

import org.springframework.http.HttpStatus
import org.springframework.http.ResponseEntity
import org.springframework.web.bind.annotation.*
import java.util.UUID

@RestController
@RequestMapping("/users")
class UserController(private val userRepository: UserRepository, private val jobs: JobPublisher) {

    @GetMapping
    fun list(): List<User> = userRepository.findAll()

    @GetMapping("/{id}")
    fun getById(@PathVariable id: UUID): ResponseEntity<User> {
        val item = userRepository.findById(id).orElse(null)
            ?: return ResponseEntity.notFound().build()
        return ResponseEntity.ok(item)
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    fun create(@RequestBody body: User): User = userRepository.save(body)
        .also { jobs.publish("""{"event":"user.created","id":"${it.id}"}""") }

    @PutMapping("/{id}")
    fun update(@PathVariable id: UUID, @RequestBody body: User): ResponseEntity<User> {
        if (!userRepository.existsById(id)) return ResponseEntity.notFound().build()
        val updated = body.copy(id = id)
        return ResponseEntity.ok(userRepository.save(updated))
    }

    @DeleteMapping("/{id}")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    fun delete(@PathVariable id: UUID) {
        if (!userRepository.existsById(id)) throw org.springframework.web.server.ResponseStatusException(
            org.springframework.http.HttpStatus.NOT_FOUND
        )
        userRepository.deleteById(id)
    }
}

package dev.helios.test_app

import org.springframework.cache.annotation.CacheEvict
import org.springframework.cache.annotation.Cacheable
import org.springframework.data.jpa.repository.JpaRepository
import java.util.Optional
import java.util.UUID

/** Cache-aside on reads by id (Redis, 60s TTL); saves and deletes evict the entry. */
interface UserRepository : JpaRepository<User, UUID> {
    @Cacheable("users", key = "#p0", unless = "#result == null")
    override fun findById(id: UUID): Optional<User>

    @CacheEvict("users", key = "#p0.id", condition = "#p0.id != null")
    override fun <S : User> save(entity: S): S

    @CacheEvict("users", key = "#p0")
    override fun deleteById(id: UUID)
}

