    @Test
    fun `GET users returns 401 without token`() {
        mvc.perform(
            request(HttpMethod.GET, "/users")
        )
            .andExpect(status().`is`(401))
    }

    @Test
    fun `GET users returns 200 with token`() {
        mvc.perform(
            request(HttpMethod.GET, "/users")
                .with(jwt())
        )
            .andExpect(status().`is`(200))
            .andExpect(content().contentTypeCompatibleWith(MediaType.APPLICATION_JSON))
            .andExpect(jsonPath("\$").isArray)
    }

    @Test
    fun `POST users returns 401 without token`() {
        mvc.perform(
            request(HttpMethod.POST, "/users")
                .contentType(MediaType.APPLICATION_JSON)
                .content("""{"name":"${unique()}","email":"${unique()}","active":true,"createdAt":"2024-01-01T00:00:00Z"}""")
